function createRegionWrapper(level,layerId,idSuffix=""){const wrapper=document.createElement("div");const layerPrefix=layerId==="modal"?"modal-":"";const suffix=idSuffix?`-${idSuffix}`:"";wrapper.id=`wbAWrap-${layerPrefix}${level}${suffix}`;return wrapper}function createDuplicateRegions(wrapper,level,regionCount,layerId,dictionary,idSuffix=""){const result=new Array(regionCount).fill(0).map((el,i)=>{const region=createRegion(level,i,layerId,dictionary,"log",idSuffix);wrapper.appendChild(region);return region});return result}function createRegion(level,index,layerId,dictionary,role="log",idSuffix=""){const region=document.createElement("div");region.setAttribute("role",role);region.setAttribute("aria-live",level);region.classList.add("wbARegion");const layerNameForId=layerId==="modal"?`${layerId}-`:"";const suffix=idSuffix?`-${idSuffix}`:"";const id=`wbARegion-${layerNameForId}${level}${index}${suffix}`;region.id=id;region.setAttribute("data-testid",id);dictionary.set(id,{id,levelIndex:index,level,element:region,layerId});return region}function removeMessage(messageElement,removalDelay){setTimeout(()=>{messageElement.remove();},removalDelay);}

function alternateIndex(index,count){index+=1;index=index%count;return index}function createDebounceFunction(context,callback,debounceThreshold){let timeoutId=null;const debouncedFn=(...args)=>{return new Promise(resolve=>{const later=()=>{const result=callback.apply(context,args);if(timeoutId){clearTimeout(timeoutId);}return resolve(result)};if(timeoutId!==null){clearTimeout(timeoutId);}timeoutId=setTimeout(()=>{later();},debounceThreshold);})};debouncedFn.updateWaitTime=newWaitTime=>{debounceThreshold=newWaitTime;};return debouncedFn}

const REMOVAL_TIMEOUT_DELAY=5e3;const DEFAULT_WAIT_THRESHOLD=250;class Announcer{static getInstance(targetElement){if(!Announcer._instance){Announcer._instance=new Announcer(targetElement);}return Announcer._instance}hasActiveModal(){return this.modalNodes.size>0}init(id){this.node=document.createElement("div");this.node.id=id;this.node.setAttribute("data-testid",id);Object.assign(this.node.style,srOnly);this.initRegionsForLayer(false,this.node,this.targetElement);}initRegionsForLayer(isModalContext,nodeRef,targetElement,idSuffix=""){const layerId=isModalContext?"modal":"document";const aWrapper=createRegionWrapper("assertive",layerId,idSuffix);createDuplicateRegions(aWrapper,"assertive",this.regionFactory.get(layerId)?.count??2,layerId,this.dictionary,idSuffix);nodeRef.appendChild(aWrapper);const pWrapper=createRegionWrapper("polite",layerId,idSuffix);createDuplicateRegions(pWrapper,"polite",this.regionFactory.get(layerId)?.count??2,layerId,this.dictionary,idSuffix);nodeRef.appendChild(pWrapper);targetElement.append(nodeRef);}reattachNodes(){const announcerNode=document.getElementById(this.topLevelId);if(announcerNode===null){return}this.node=announcerNode;announcerNode.querySelectorAll("[id^='wbARegion']").forEach(region=>{const layerId=region.id.startsWith("wbARegion-modal-")?"modal":"document";this.dictionary.set(region.id,{id:region.id,levelIndex:parseInt(region.id.charAt(region.id.length-1)),layerId,level:region.getAttribute("aria-live"),element:region});});}attachAnnouncerToModal(modalElement){const suffix=String(++this.modalCounter);const modalAnnouncerId=`${this.topLevelId}-modal-${suffix}`;const existing=modalElement.querySelector(`#${modalAnnouncerId}`);if(existing){existing.querySelectorAll("[id^='wbARegion-modal-']").forEach(region=>{this.dictionary.set(region.id,{id:region.id,levelIndex:parseInt(region.id.charAt(region.id.length-1)),level:region.getAttribute("aria-live"),element:region,layerId:"modal"});});this.modalNodes.set(modalElement,existing);return}const modalNode=document.createElement("div");modalNode.id=modalAnnouncerId;modalNode.setAttribute("data-testid",modalAnnouncerId);Object.assign(modalNode.style,srOnly);this.initRegionsForLayer(true,modalNode,modalElement,suffix);this.modalNodes.set(modalElement,modalNode);}detachAnnouncerFromModal(modalElement){const modalNode=this.modalNodes.get(modalElement);if(!modalNode){return}modalNode.querySelectorAll("[id^='wbARegion-modal-']").forEach(region=>{this.dictionary.delete(region.id);});modalNode.parentElement?.removeChild(modalNode);this.modalNodes.delete(modalElement);if(this.modalNodes.size===0){const modalFactory=this.regionFactory.get("modal");if(modalFactory){modalFactory.aIndex=0;modalFactory.pIndex=0;}this.modalCounter=0;}}announce(message,level,inModalContext,debounceThreshold){if(debounceThreshold!==undefined){this.updateWaitThreshold(debounceThreshold);}const layerId=inModalContext?"modal":"document";const debounced=this.debouncedByLayer.get(layerId);return debounced(this,message,level,layerId)}updateWaitThreshold(debounceThreshold){this.waitThreshold=debounceThreshold;this.debouncedByLayer?.forEach(fn=>{fn.updateWaitTime(debounceThreshold);});}processAnnouncement(context,message,level,layerId){if(!context.node){context.reattachNodes();}const hasModalRegions=[...context.dictionary.values()].some(entry=>entry.layerId==="modal");const targetLayerId=layerId==="modal"&&!hasModalRegions?"document":layerId;const regions=[...context.dictionary.values()].filter(entry=>entry.level===level&&entry.layerId===targetLayerId);const newIndex=context.appendMessage(message,level,regions,targetLayerId);const layerFactory=context.regionFactory.get(targetLayerId);if(layerFactory){if(level==="assertive"){layerFactory.aIndex=newIndex;}else {layerFactory.pIndex=newIndex;}}return regions[newIndex]?.id||""}clear(id){if(!this.node){return}if(id){this.dictionary.get(id)?.element.replaceChildren();}else {this.dictionary.forEach(region=>{region.element.replaceChildren();});}}appendMessage(message,level,regionList,layerId,debounceThreshold=DEFAULT_WAIT_THRESHOLD){const layerFactory=this.regionFactory.get(layerId);if(!layerFactory){throw new Error(`Layer factory not found for layer: ${layerId}`)}let index=level==="assertive"?layerFactory.aIndex:layerFactory.pIndex;regionList[index].element.replaceChildren();index=alternateIndex(index,layerFactory.count);const messageEl=document.createElement("p");messageEl.textContent=message;regionList[index].element.appendChild(messageEl);removeMessage(messageEl,debounceThreshold+REMOVAL_TIMEOUT_DELAY);return index}reset(){this.regionFactory.forEach(value=>{value.aIndex=0;value.pIndex=0;});this.clear();}destroy(){if(this.node){this.node.parentElement?.removeChild(this.node);}this.modalNodes.forEach(modalNode=>{modalNode.parentElement?.removeChild(modalNode);});this.modalNodes.clear();Announcer._instance=null;}constructor(targetElement=document.body){this.topLevelId=`wbAnnounce`;this.node=null;this.regionFactory=new Map([["document",{count:2,aIndex:0,pIndex:0}],["modal",{count:2,aIndex:0,pIndex:0}]]);this.dictionary=new Map;this.waitThreshold=DEFAULT_WAIT_THRESHOLD;this.modalNodes=new Map;this.modalCounter=0;this.targetElement=targetElement;if(typeof document!=="undefined"){const announcerCheck=document.getElementById(this.topLevelId);if(announcerCheck===null){this.init(this.topLevelId);}else {this.reattachNodes();}this.debouncedByLayer=new Map([["document",createDebounceFunction(this,this.processAnnouncement,this.waitThreshold)],["modal",createDebounceFunction(this,this.processAnnouncement,this.waitThreshold)]]);}}}const srOnly={border:0,clip:"rect(0,0,0,0)",height:1,margin:-1,overflow:"hidden",padding:0,position:"absolute",width:1};

function initAnnouncer(props){let targetElement;if(props?.targetElement!==null){targetElement=props?.targetElement;}const announcer=Announcer.getInstance(targetElement);if(props?.debounceThreshold!==undefined){announcer.updateWaitThreshold(props?.debounceThreshold);}return announcer}

function announceMessage({message,level="polite",debounceThreshold,initialTimeout=150}){const announcer=Announcer.getInstance();if(initialTimeout>0){return new Promise(resolve=>{return setTimeout(async()=>{const result=announcer.announce(message,level,announcer.hasActiveModal(),debounceThreshold);resolve(result);},initialTimeout)})}else {return announcer.announce(message,level,announcer.hasActiveModal(),debounceThreshold)}}

function clearMessages(id){const announcer=Announcer.getInstance();if(id&&document?.getElementById(id)){announcer.clear(id);}else if(typeof document!=="undefined"){announcer.clear();}}

function attachAnnouncerToModal(modalElement){Announcer.getInstance().attachAnnouncerToModal(modalElement);}function detachAnnouncerFromModal(modalElement){Announcer.getInstance().detachAnnouncerFromModal(modalElement);}

export { announceMessage, attachAnnouncerToModal, clearMessages, detachAnnouncerFromModal, initAnnouncer };
